const API_BASE="../api/index.php";function setDateFilter(type){const today=new Date;let start=new Date,end=new Date;today.setHours(0,0,0,0),"today"===type?(start=new Date(today),end=new Date(today)):"month"===type?(start=new Date(today.getFullYear(),today.getMonth(),1),end=new Date(today.getFullYear(),today.getMonth()+1,0)):"year"===type?(start=new Date(today.getFullYear(),0,1),end=new Date(today.getFullYear(),11,31)):"all"===type&&(start=new Date(2020,0,1),end=new Date(today));const startInput=document.getElementById("start_date"),endInput=document.getElementById("end_date");startInput&&(startInput.value=formatDateToISO(start)),endInput&&(endInput.value=formatDateToISO(end)),loadReport()}function formatDateToISO(date){if(!date)return"";const d=new Date(date);let year=d.getFullYear(),month,day;return year>2400&&(year-=543),`${year}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`}function loadReport(){const startInput=document.getElementById("start_date"),endInput=document.getElementById("end_date");if(!startInput||!endInput)return;const startDate=startInput.value,endDate=endInput.value,tbody=document.getElementById("reportTableBody"),countSpan=document.getElementById("totalCount");tbody&&(tbody.innerHTML='<tr><td colspan="6" class="py-5 text-center"><i class="fas fa-spinner fa-spin fa-2x text-secondary"></i><br>กำลังประมวลผล...</td></tr>'),countSpan&&(countSpan.innerText="0"),fetch(`${API_BASE}?dev=report&start_date=${startDate}&end_date=${endDate}`).then(res=>res.json()).then(res=>{"success"===res.status&&res.data.length>0?(renderTable(res.data),countSpan&&(countSpan.innerText=numberFormat(res.total_count))):(tbody&&(tbody.innerHTML='<tr><td colspan="6" class="py-5 text-center text-muted">ไม่พบข้อมูลในช่วงเวลาที่เลือก</td></tr>'),countSpan&&(countSpan.innerText="0"))}).catch(err=>{console.error(err),tbody&&(tbody.innerHTML='<tr><td colspan="6" class="py-5 text-center text-danger">เกิดข้อผิดพลาดในการโหลดข้อมูล</td></tr>')})}function renderTable(data){const tbody=document.getElementById("reportTableBody");if(!tbody)return;let html="",currentDept=null,runningNo=1;data.forEach(row=>{const rowDept=row.sender_dept||"ไม่ระบุแผนก (Unknown)";rowDept!==currentDept&&(currentDept=rowDept,html+=`\n                <tr class="table-light border-bottom border-2">\n                    <td colspan="6" class="py-3 ps-4 text-primary fw-bold" style="font-size: 1rem; background-color: #f8f9fa;">\n                        <i class="fas fa-building me-2"></i> แผนก: ${currentDept}\n                    </td>\n                </tr>\n            `);let statusBadge=`<span class="badge bg-secondary">${row.current_status}</span>`;"Received"===row.current_status?statusBadge='<span class="badge bg-warning text-dark">Received</span>':"Sent"===row.current_status?statusBadge='<span class="badge bg-info text-dark">Sent</span>':"Done"!==row.current_status&&"ได้รับแล้ว"!==row.current_status||(statusBadge='<span class="badge bg-success">Success</span>');const scanner=row.scanner_name?`<span class="text-success"><i class="fas fa-qrcode me-1"></i>${row.scanner_name}</span>`:'<span class="text-muted">-</span>';html+=`\n            <tr>\n                <td class="text-center text-muted">${runningNo++}</td>\n                <td><small>${row.created_at_fmt}</small></td>\n                <td><span class="text-dark fw-bold">${row.document_code}</span></td>\n                <td>${row.title}</td>\n                <td><small>${scanner}</small></td>\n                <td class="text-center">${statusBadge}</td>\n            </tr>\n        `}),tbody.innerHTML=html}function numberFormat(num){return new Intl.NumberFormat("th-TH").format(num)}function exportTableToExcel(tableID,filename=""){const table=document.getElementById(tableID);if(!table)return;let html="<table border='1'>";const headers=table.querySelectorAll("thead th");if(headers.length>0){html+="<tr style='background-color: #eee;'>";for(let cell of headers)html+="<th>"+cell.innerText+"</th>";html+="</tr>"}const tbody=table.querySelector("tbody"),rows=tbody?tbody.rows:table.rows;for(let i=0;i<rows.length;i++){const isHeaderRow=1===rows[i].cells.length,bgStyle=isHeaderRow?"style='background-color: #cce5ff; font-weight: bold;'":"";html+=`<tr ${bgStyle}>`;for(let cell of rows[i].cells){const colspan=cell.getAttribute("colspan")?` colspan="${cell.getAttribute("colspan")}"`:"";html+=`<td${colspan}>`+cell.innerText+"</td>"}html+="</tr>"}html+="</table>";const link=document.createElement("a"),blob=new Blob([html],{type:"application/vnd.ms-excel"});link.href=URL.createObjectURL(blob),link.download=filename+".xls",link.click()}document.addEventListener("DOMContentLoaded",()=>{const searchForm=document.getElementById("searchForm");searchForm&&searchForm.addEventListener("submit",e=>e.preventDefault());const filterBtns=document.querySelectorAll(".js-date-filter");filterBtns.forEach(btn=>{btn.addEventListener("click",(function(){const filterType=this.getAttribute("data-filter");setDateFilter(filterType)}))});const btnSearch=document.getElementById("btnSearch");btnSearch&&btnSearch.addEventListener("click",loadReport);const btnReset=document.getElementById("btnReset");btnReset&&btnReset.addEventListener("click",()=>{setDateFilter("month")});const btnPrint=document.getElementById("btnPrint");btnPrint&&btnPrint.addEventListener("click",()=>window.print());const btnExport=document.getElementById("btnExport");btnExport&&btnExport.addEventListener("click",()=>exportTableToExcel("reportTable","Report_Document_Grouped")),loadReport()});